237	    /**
238	     * The maximum number of owners that may be registered in any single city.
239	     */
240	    private static final long MAX_OWNERS_PER_CITY = 8;
241	
242	    /**
243	     * Determines whether the given city has already reached its owner limit. Owners are matched to
244	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
245	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
246	     * no further owners may be created there.
247	     *
248	     * @param city the city of the new owner, may be {@code null}
249	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
250	     */
251	    private boolean hasReachedCityOwnerLimit(String city) {
252	        String normalized = normalize(city);
253	        long ownersInCity = this.clinicService.findAllOwners().stream()
254	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
255	            .count();
256	        return ownersInCity >= MAX_OWNERS_PER_CITY;
257	    }
