259	    /**
260	     * Builds the customer code for a newly created owner, formatted as
261	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
262	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
263	     *
264	     * @param city the city of the new owner
265	     * @return the assigned customer code
266	     */
267	    private String nextCustomerCode(String city) {
268	        long ownersInCity = this.clinicService.findAllOwners().stream()
269	            .filter(existing -> Objects.equals(
270	                normalize(existing.getCity()), normalize(city)))
271	            .count();
272	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
273	    }
