326	    /**
327	     * Determines whether the given telephone number is already used by any other owner.
328	     *
329	     * @param owner the candidate owner
330	     * @return {@code true} if an owner with the same telephone number already exists in the data store
331	     */
332	    private boolean isDuplicateOwner(Owner owner) {
333	        return this.clinicService.findAllOwners().stream()
334	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
335	    }
